<?php
declare(strict_types=1);
final class Database {
    private static ?PDO $pdo = null;
    public static function connection(array $config): PDO { if(self::$pdo)return self::$pdo;$db=$config['database'];self::$pdo=new PDO($db['dsn'],$db['user'],$db['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);self::migrateCompat(self::$pdo);self::seedAdmins(self::$pdo);return self::$pdo; }
    private static function migrateCompat(PDO $pdo):void{try{$has=$pdo->query("SHOW COLUMNS FROM users LIKE 'role'")->fetch();if(!$has)$pdo->exec("ALTER TABLE users ADD COLUMN role ENUM('admin','teacher','student','staff') NOT NULL DEFAULT 'student'");$hasUser=$pdo->query("SHOW COLUMNS FROM users LIKE 'username'")->fetch();if(!$hasUser){$pdo->exec("ALTER TABLE users ADD COLUMN username VARCHAR(80) NULL AFTER email");$pdo->exec("UPDATE users SET username=CONCAT('user_',id) WHERE username IS NULL OR username='' ");$pdo->exec("ALTER TABLE users MODIFY username VARCHAR(80) NOT NULL UNIQUE");}}catch(Throwable $e){/* O instalador aplica o schema quando a tabela ainda não existe. */}}
    private static function seedAdmins(PDO $pdo):void{try{$has=$pdo->query("SHOW TABLES LIKE 'users'")->fetch();if(!$has)return;$accounts=[['admin','Admin','admin@local.zystem', 'admin'],['zelipe','Zelipe','zelipe@local.zystem','Isadora']];foreach($accounts as [$username,$display,$email,$password]){$q=$pdo->prepare('SELECT id FROM users WHERE username=? OR email=? LIMIT 1');$q->execute([$username,$email]);$id=$q->fetchColumn();if($id===false){$ins=$pdo->prepare('INSERT INTO users(email,username,password_hash,display_name,role) VALUES(?,?,?,?,\'admin\')');$ins->execute([$email,$username,password_hash($password,PASSWORD_DEFAULT),$display]);}else{$up=$pdo->prepare("UPDATE users SET username=?,display_name=?,role='admin' WHERE id=?");$up->execute([$username,$display,$id]);}}}catch(Throwable $e){/* Não impede a aplicação quando o banco ainda não foi inicializado. */}}
}
?>
